 public static func find(_ id:String)->ServiceIdentity? {all.first{$0.id==id || $0.product==id}}
 public static func opticalSize(_ size:Double)->Int {size<=19 ? 18:size<=21 ? 20:22}
 public func symbol(_ size:Double)->String {"provider.\(product).compact"+((!existing || ["codex","kimi"].contains(product)) ? ".p\(Self.opticalSize(size))":"")}
 public var hasMicroGrid:Bool {["codex","kimi","elevenlabs","opencode","opencodego"].contains(product)}
 public var opticalOffset:CGSize {product=="kimi" ? CGSize(width:0.5,height:-0.5):.zero}
 public func targetInk(_ size:Double)->Double {ink[Self.opticalSize(size)==18 ? 0:Self.opticalSize(size)==20 ? 1:2]}
 public func nativeInk(_ size:Double,_ weight:Int)->[Double] {Self.metrics[symbol(size)]?[weight] ?? [0,0,0.70459,0.70459]}
}

/// Standalone menu-bar identity specimen. Composition layers retain their own layout.
struct ServiceIdentityIcon:View {
 var service:ServiceIdentity
 var size:Double
 var weight:Font.Weight = .regular
 var zoom:Double = 1
 var monochrome=false
 @Environment(\.displayScale) private var density
 var body:some View {
  let wi=GaugeCalibration.Glyph.weights.firstIndex(of:weight) ?? 3
  let m=service.nativeInk(size,wi)
  let font=service.targetInk(size)/max(m[2],m[3])*zoom
  let offset=service.opticalOffset
  let inkX=size*zoom/2+offset.width*zoom
  let inkY=size*zoom/2+offset.height*zoom
  let step=zoom/density
  let x=service.hasMicroGrid ? ((inkX-m[2]*font/2)/step).rounded()*step+m[2]*font/2:inkX
  let y=service.hasMicroGrid ? ((inkY-m[3]*font/2)/step).rounded()*step+m[3]*font/2:inkY
  Image(service.symbol(size)).font(.system(size:font,weight:weight)).imageScale(.small)
   .symbolRenderingMode(monochrome ? .monochrome:.hierarchical)
   .position(x:x-m[0]*font,y:y-m[1]*font)
   .frame(width:size*zoom,height:size*zoom)
   .accessibilityLabel(service.name)
 }
}
